"use client";

import { useState } from "react";
import { Check, X, MessageCircleQuestion } from "lucide-react";
import { cn } from "@/lib/utils";
import { panel, secondary } from "@/lib/takt-surface";

export type ExerciseCase = {
  input: string;
  expected: boolean;
  actual: boolean;
};
const sample: ExerciseCase[] = [
  { input: "UI-7", expected: true, actual: true },
  { input: "UI-42", expected: true, actual: false },
  { input: "UI-X", expected: false, actual: false },
];

export function TestResults({
  results = sample,
  onAsk,
  className,
}: {
  results?: ExerciseCase[];
  onAsk?: (result: ExerciseCase, trigger: HTMLButtonElement) => void;
  className?: string;
}) {
  const [choice, setChoice] = useState<number | null>(null);
  const failed = results.findIndex((row) => row.actual !== row.expected);
  const index =
    choice !== null && results[choice] ? choice : Math.max(0, failed);
  const row = results[index];
  return (
    <section className={cn(panel, "grid w-72 max-w-full gap-3", className)}>
      <header className="flex items-baseline justify-between gap-2">
        <strong>Tests</strong>
        <output className="font-mono text-xs tabular-nums">
          {results.filter((r) => r.expected === r.actual).length} /{" "}
          {results.length}
        </output>
      </header>
      <div className="flex flex-wrap gap-1.5">
        {results.map((test, i) => {
          const ok = test.expected === test.actual;
          const Icon = ok ? Check : X;
          return (
            <button
              key={i}
              type="button"
              aria-pressed={i === index}
              aria-label={String(i + 1).padStart(2, "0") + " · " + test.input + (ok ? " · passed" : " · failed")}
              onClick={() => setChoice(i)}
              className="flex min-h-9 items-center gap-1 rounded-md border px-2 font-mono text-xs aria-pressed:border-primary aria-pressed:bg-primary/10 motion-safe:transition-colors"
            >
              <Icon size={13} />
              {String(i + 1).padStart(2, "0")}
            </button>
          );
        })}
      </div>
      {row ? (
        <div
          key={index}
          className="grid gap-2 border-t pt-2 motion-safe:animate-in motion-safe:fade-in motion-safe:slide-in-from-bottom-1"
        >
          <code className="break-all">{JSON.stringify(row.input)}</code>
          <dl className="grid grid-cols-2 gap-2 text-xs">
            <div>
              <dt className="text-muted-foreground">Expected</dt>
              <dd className="font-mono">{String(row.expected)}</dd>
            </div>
            <div>
              <dt className="text-muted-foreground">Actual</dt>
              <dd className="font-mono">{String(row.actual)}</dd>
            </div>
          </dl>
          {onAsk && row.actual !== row.expected && (
            <button
              type="button"
              className={secondary}
              onClick={(event) => onAsk(row, event.currentTarget)}
            >
              <MessageCircleQuestion size={14} />
              Ask about this test
            </button>
          )}
        </div>
      ) : (
        <p className="text-muted-foreground">No test cases yet</p>
      )}
    </section>
  );
}

// Semantic shadcn colors keep the surfaces usable in a host project's own theme.
export const panel =
  "rounded-2xl border border-foreground/10 bg-card p-4 text-sm text-card-foreground shadow-[0_2px_5px_#0000000a,0_8px_18px_-12px_#0003]";
export const field =
  "min-h-10 min-w-0 w-full rounded-xl border border-foreground/10 bg-muted/70 px-3 text-sm text-foreground outline-none motion-safe:transition-[background-color,box-shadow] focus:bg-background focus:ring-1 focus:ring-foreground/35";
export const action =
  "inline-flex min-h-10 cursor-pointer items-center justify-center gap-2 rounded-xl border border-foreground/10 bg-primary px-3.5 py-2 text-sm font-semibold text-primary-foreground shadow-sm outline-offset-4 motion-safe:transition-[transform,box-shadow] motion-safe:active:translate-y-px motion-safe:active:scale-[.97] disabled:cursor-default disabled:opacity-50";
export const secondary =
  "inline-flex min-h-9 cursor-pointer items-center justify-center gap-1.5 rounded-lg border border-foreground/10 bg-background px-3 text-xs font-medium text-foreground outline-offset-2 hover:bg-muted motion-safe:transition-[transform,background-color] motion-safe:active:scale-[.96] disabled:cursor-default disabled:opacity-45";
